/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::ELECTION_UNKNOWN,
    error_codes::NOT_CLOSED,
    error_codes::TARGETS_MISMATCH,
    error_codes::ALREADY_AUTHORIZED,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `voting/trustees/authorize:electionUnknown`
    ///
    /// No election with this identifier exists for this community.
    ///
    /// Declared `retryable: false`.
    pub const ELECTION_UNKNOWN: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "voting/trustees/authorize:electionUnknown",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `voting/trustees/authorize:notClosed`
    ///
    /// Voting has not closed, or the election is not sealed or tallied-encrypted, or its key never formed.
    ///
    /// Declared `retryable: false`.
    pub const NOT_CLOSED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "voting/trustees/authorize:notClosed",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `voting/trustees/authorize:targetsMismatch`
    ///
    /// The ballot box's decryption targets are not the ones the community authorized: another count, another digest, or another head.
    ///
    /// Declared `retryable: false`.
    pub const TARGETS_MISMATCH: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "voting/trustees/authorize:targetsMismatch",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `voting/trustees/authorize:alreadyAuthorized`
    ///
    /// The community has already authorized another set of targets for this election.
    ///
    /// Declared `retryable: false`.
    pub const ALREADY_AUTHORIZED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "voting/trustees/authorize:alreadyAuthorized",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
